{"query": "
SELECT DISTINCT context, stat_holder_type, stat_repository_type 
FROM stats 
WHERE stat_repository_type IN ('baseball_offensive_stats', 'baseball_defensive_stats')
ORDER BY context, stat_holder_type, stat_repository_type;
"}

{"query": "
-- Check display_names for persons
SELECT entity_type, COUNT(*) as cnt FROM display_names GROUP BY entity_type;
"}

{"query": "
-- Check if defensive stats have data
SELECT id, putouts, assists, errors, fielding_percentage FROM baseball_defensive_stats WHERE id <= 100 AND putouts IS NOT NULL LIMIT 10;
"}

{"query": "
-- Investigate where the actual data is in defensive stats 
SELECT id, putouts, assists, errors, fielding_percentage FROM baseball_defensive_stats 
WHERE putouts IS NOT NULL LIMIT 10;
"}

{"query": "
-- Look at what data is available in baseball_defensive_stats
SELECT id, double_plays, triple_plays, putouts, assists, errors, fielding_percentage, defensive_average, errors_passed_ball, errors_catchers_interference 
FROM baseball_defensive_stats 
WHERE errors IS NOT NULL LIMIT 10;
"}

{"query": "
-- Look at offensive stats for a regular season person
SELECT id, at_bats, hits, runs_scored, rbi, home_runs, average
FROM baseball_offensive_stats 
WHERE id = 988;
"}

